package com.kampotourism.itinerary;
import com.kampotourism.common.PageResponse; import com.kampotourism.common.i18n.LanguageResolver; import com.kampotourism.itinerary.ItineraryDtos.*; import java.time.Duration; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/itineraries") public class ItineraryController { private final ItineraryService service; private final LanguageResolver languages; public ItineraryController(ItineraryService service,LanguageResolver languages){this.service=service;this.languages=languages;} @GetMapping public ResponseEntity<PageResponse<Card>> list(@RequestParam(required=false) Boolean featured,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="12")int size,@RequestParam(required=false)String lang,@RequestHeader(value=HttpHeaders.ACCEPT_LANGUAGE,required=false)String accept){String l=languages.resolve(lang,accept);return cached(service.list(featured,page,size,l),l);}@GetMapping("/{slug}") public ResponseEntity<Detail> get(@PathVariable String slug,@RequestParam(required=false)String lang,@RequestHeader(value=HttpHeaders.ACCEPT_LANGUAGE,required=false)String accept){Detail d=service.get(slug,languages.resolve(lang,accept));return cached(d,d.language());}private static <T>ResponseEntity<T> cached(T body,String lang){return ResponseEntity.ok().cacheControl(CacheControl.maxAge(Duration.ofMinutes(5)).cachePublic()).header(HttpHeaders.CONTENT_LANGUAGE,lang).header(HttpHeaders.VARY,HttpHeaders.ACCEPT_LANGUAGE).body(body);}}
